css:
* {
    font-family: 'Times New Roman', Times, serif;
    line-height: 1.4;
}

body {
    font-size: 12pt;
    color: #1a1a1a;
    margin: 25mm;
    background: #ffffff;
    line-height: 1.6;
}

/* Company Header Styling */
h3 {
    font-size: 18pt;
    text-align: center;
    color: #1a1a1a;
    margin-bottom: 15pt;
    font-weight: bold;
    letter-spacing: 0.5pt;
    text-transform: uppercase;
}

/* Section Headers */
h4 {
    font-size: 14pt;
    margin-top: 25pt;
    margin-bottom: 10pt;
    color: #1a1a1a;
    font-weight: bold;
    border-bottom: 2pt solid #2c3e50;
    padding-bottom: 5pt;
    letter-spacing: 0.3pt;
}

/* Subsection Headers */
h5 {
    font-size: 12pt;
    margin-top: 20pt;
    margin-bottom: 8pt;
    color: #2c3e50;
    font-weight: bold;
    letter-spacing: 0.2pt;
}

strong {
    color: #1a1a1a;
    font-weight: bold;
}

/* Paragraph Styling */
p {
    text-align: justify;
    margin-bottom: 10pt;
    text-indent: 20pt;
    line-height: 1.8;
}

/* Professional Table Styling */
table, table th, table td {
    border-collapse: collapse;
    padding: 8pt 10pt;
    text-align: left;
    vertical-align: top;
    background: #ffffff;
    font-size: 10pt;
}

table {
    width: 100%;
    margin-bottom: 20pt;
    background: #ffffff;
    border: 2pt solid #2c3e50;
    box-shadow: 0 2pt 4pt rgba(0,0,0,0.1);
}

table th {
    font-size: 11pt;
    font-weight: bold;
    color: #2c3e50;
    background: #f8f9fa;
    border-left: 1pt solid #2c3e50;
    border-right: 1pt solid #2c3e50;
    border-top: none;
    border-bottom: 2pt solid #2c3e50;
    text-align: center;
    padding: 10pt 8pt;
    letter-spacing: 0.2pt;
}

table tr:last-child td {
    border-bottom: 2pt solid #2c3e50;
}

table th:first-child {
    border-left: 2pt solid #2c3e50;
}

table th:last-child {
    border-right: 2pt solid #2c3e50;
}

table td {
    border-top: none;
    border-bottom: 1pt solid #e9ecef;
    border-left: none;
    border-right: none;
    padding: 8pt 10pt;
}

table td:first-child {
    border-left: 2pt solid #2c3e50;
}

table td:last-child {
    border-right: 2pt solid #2c3e50;
}

/* List Styling */
ol {
    padding-left: 25pt;
    margin-top: 10pt;
    margin-bottom: 15pt;
}

ol li {
    margin-bottom: 8pt;
    line-height: 1.6;
}

/* Horizontal Rule */
hr {
    margin-top: 25pt;
    margin-bottom: 20pt;
    border: none;
    border-top: 2pt solid #2c3e50;
    width: 100%;
}

/* Signature and Place/Date Tables */
.signature-table,
.place-date-table {
    width: 100%;
    font-size: 10pt;
    margin-top: 30pt;
    border: none;
    box-shadow: none;
}

.signature-table td {
    text-align: center;
    padding-top: 25pt;
    border: none;
    font-weight: bold;
}

.place-date-table td {
    padding: 5pt 0;
    border: none;
    font-weight: bold;
}

/* Section and Note Formatting */
.section-heading {
    font-size: 16pt;
    color: #1a1a1a;
    margin-top: 30pt;
    margin-bottom: 15pt;
    font-weight: bold;
    text-align: center;
    text-transform: uppercase;
    letter-spacing: 0.5pt;
    border-bottom: 3pt solid #2c3e50;
    padding-bottom: 10pt;
}

.note-title {
    font-size: 12pt;
    color: #2c3e50;
    font-weight: bold;
    margin-top: 20pt;
    margin-bottom: 10pt;
    border-left: 4pt solid #3498db;
    padding-left: 10pt;
    letter-spacing: 0.2pt;
}

.note-desc {
    font-size: 10pt;
    color: #34495e;
    margin-bottom: 12pt;
    text-align: justify;
    line-height: 1.7;
    text-indent: 20pt;
}

/* Report Table Specific Styling */
.report-table {
    margin-top: 15pt;
    margin-bottom: 25pt;
}

.report-table th {
    background: #ecf0f1;
    color: #2c3e50;
    font-weight: bold;
    text-align: center;
}

.report-table td {
    border-bottom: 1pt solid #bdc3c7;
}

/* Print/PDF Optimizations */
.page-break {
    page-break-before: always;
}

@media print {
    body {
        margin: 20mm;
        font-size: 11pt;
    }

    .page-break {
        display: block;
        page-break-before: always;
    }

    table {
        page-break-inside: avoid;
    }

    h3, h4, .section-heading {
        page-break-after: avoid;
    }

    .note-title {
        page-break-after: avoid;
    }
}

/* Additional Professional Styling */
.company-header {
    text-align: center;
    margin-bottom: 30pt;
    padding-bottom: 20pt;
    border-bottom: 3pt double #2c3e50;
}

.auditor-section {
    margin-top: 25pt;
    padding: 20pt;
    background: #f8f9fa;
    border-left: 5pt solid #3498db;
    border-radius: 5pt;
}

.legal-text {
    font-size: 10pt;
    line-height: 1.8;
    text-align: justify;
    color: #2c3e50;
}

.signature-line {
    border-top: 1pt solid #2c3e50;
    margin-top: 15pt;
    padding-top: 5pt;
    text-align: center;
    font-weight: bold;
    font-size: 10pt;
}

/* Highlight styling for sections */
.section-highlight {
    background-color: #fff3cd !important;
    border: 2pt solid #ffc107 !important;
    border-radius: 5pt;
    transition: all 0.3s ease;
}

/* Clickable row styling */
.clickable-row {
    cursor: pointer;
    transition: background-color 0.2s ease;
}

.clickable-row:hover {
    background-color: #e9ecef !important;
}
